"""
AgroPulse 30-Year Agro-Climatic Normal Database (1991-2020 WMO Standard Normals).
Provides monthly minimum temperature, maximum temperature, solar radiation, precipitation,
relative humidity, wind speed, and Penman-Monteith reference evapotranspiration (ET0)
for 140 major agricultural benchmark meteorological stations globally.
"""

from typing import Dict, List, Optional
from pydantic import BaseModel, Field


class MonthlyClimateNormal(BaseModel):
    month: int
    t_min_c: float
    t_max_c: float
    t_mean_c: float
    precipitation_mm: float
    solar_radiation_mj_m2_day: float
    relative_humidity_pct: float
    wind_speed_m_s: float
    et0_penman_monteith_mm_day: float


class WeatherStationNormals(BaseModel):
    station_id: str
    station_name: str
    country: str
    latitude: float
    longitude: float
    elevation_m: float
    koppen_climate_class: str
    annual_precipitation_mm: float
    aridity_index: float
    monthly_normals: List[MonthlyClimateNormal]


