def get_station_normals(station_id: str) -> Optional[WeatherStationNormals]:
    return AGRO_CLIMATIC_STATIONS.get(station_id)

def list_all_stations() -> List[WeatherStationNormals]:
    return list(AGRO_CLIMATIC_STATIONS.values())
